        push("gemini-2.0-flash", TokenRateKind::CacheWrite, 0.10);
        push("gemini-2.0-flash", TokenRateKind::CacheRead, 0.025);
        push("gemini-2.0-flash", TokenRateKind::Output, 0.40);

