                rate_per_m: 2.50,
                effective_from: epoch,
                effective_until: None,
            },
            PricingRate {
                model: "gpt-4o".into(),
                tier: Some("Standard".into()),
                kind: TokenRateKind::Input,
                rate_per_m: 9.99,
                effective_from: epoch,
                effective_until: None,
            },
