182	        message_id: &str,
183	    ) -> Result<MessageParts, IngestionError> {
184	        let parts: Vec<serde_json::Value> = stmt
185	            .query_map([message_id], |row| row.get::<_, String>(0))?
186	            .collect::<Result<Vec<_>, _>>()?
187	            .into_iter()
188	            .filter_map(|raw| serde_json::from_str(&raw).ok())
189	            .collect();
190	
191	        let mut tool_calls = SmallVec::new();
192	        let mut tool_results = SmallVec::new();
193	        let mut text_segments = Vec::new();
194	
195	        for part in &parts {
196	            match part.get("type").and_then(|v| v.as_str()) {
197	                Some("text") => {
198	                    if let Some(t) = part.get("text").and_then(|v| v.as_str()) {
199	                        text_segments.push(t.to_string());
200	                    }
201	                }
202	                Some("tool") => {
203	                    let tool_name = part.get("tool").and_then(|v| v.as_str()).unwrap_or("");
204	                    let call_id = part.get("callID").and_then(|v| v.as_str()).unwrap_or("");
205	                    let state = part.get("state");
206	                    let input = state.and_then(|s| s.get("input")).cloned().unwrap_or(serde_json::Value::Null);
207	                    let status = state.and_then(|s| s.get("status")).and_then(|v| v.as_str()).unwrap_or("");
208	                    // Real data confirmed "completed" as the success status; no real error
209	                    // example was observed, so "error" is the defensible opposite (a common
210	                    // state-machine convention), not a confirmed exact string -- revisit if a
211	                    // real error-state row is observed with a different value.
212	                    let is_error = status == "error";
213	                    let output_str = state
214	                        .and_then(|s| s.get("output"))
215	                        .and_then(|v| v.as_str())
216	                        .map(str::to_string)
217	                        .unwrap_or_default();
218	
219	                    let intent = classify_tool_intent(tool_name, &input);
220	
221	                    tool_calls.push(CanonicalToolCall {
222	                        call_id: CompactString::new(call_id),
223	                        tool_name: CompactString::new(tool_name),
224	                        intent,
225	                        raw_arguments: input,
226	                    });
227	                    tool_results.push(CanonicalToolResult {
228	                        call_id: CompactString::new(call_id),
229	                        output_bytes: output_str.len(),
230	                        line_count: output_str.lines().count(),
231	                        is_error,
232	                        error_class: if is_error { Some(CompactString::new("ToolError")) } else { None },
233	                        truncated_output: None,
234	                        otel_span_id: None,
235	                    });
236	                }
237	                _ => {}
238	            }
239	        }
240	
241	        let text = if text_segments.is_empty() { None } else { Some(text_segments.join("\n")) };
242	        Ok((tool_calls, tool_results, text))
243	    }
244	}
