1	use chrono::{DateTime, Utc};
2	use compact_str::CompactString;
3	use serde::{Deserialize, Serialize};
4	use std::collections::HashMap;
5	
6	use crate::pricing::{PricingTable, TokenRateKind};
7	use crate::turn::TurnTokenUsage;
8	
9	/// A cost value that may or may not be genuinely known, pairing the dollar amount with
10	/// [`TokenEconomics::is_fully_priced`]'s recognition signal at the type level (CRIT-LUMEN-171).
11	/// The (`f64` total_cost_usd, `bool` is_fully_priced) pair those fields form is still the right
12	/// representation for computation and storage -- summing costs across turns/sessions and
13	/// persisting to SQL both need the raw numeric value regardless of pricing status -- but at the
14	/// point a cost is surfaced to a human (a CLI table, a report), reading `total_cost_usd` alone
15	/// silently mis-displays an unpriced session as a suspicious-looking `$0.00`. `Cost` makes that
16	/// mistake a compile error at the display boundary: obtain one via [`TokenEconomics::cost`] and
17	/// the `Unpriced` case must be handled to get a number out at all.
18	#[derive(Debug, Clone, Copy, PartialEq)]
19	pub enum Cost {
20	    /// A dollar amount computed from at least one seeded `PricingTable` row.
21	    Priced(f64),
22	    /// No seeded pricing matched the model -- the real cost is unknown, not `$0.00`.
23	    Unpriced,
24	}
25	
26	impl Cost {
27	    /// Formats this cost for display: `$X.XXXX` when priced, or `unpriced_label` verbatim when
28	    /// not (e.g. `"unknown (model not in pricing table)"`).
29	    pub fn format_usd(&self, unpriced_label: &str) -> String {
30	        match self {
31	            Cost::Priced(v) => format!("${v:.4}"),
32	            Cost::Unpriced => unpriced_label.to_string(),
33	        }
34	    }
35	}
36	
37	/// One turn's token usage plus the pricing context (timestamp, tier) needed to price it
38	/// independently -- required so a session whose turns straddle a price-change boundary (or a
39	/// service_tier change) is priced correctly on both sides of the boundary.
40	#[derive(Debug, Clone, PartialEq)]
41	pub struct TurnPricingInput {
42	    pub usage: TurnTokenUsage,
43	    pub timestamp: DateTime<Utc>,
44	    pub tier: Option<CompactString>,
45	}
46	
47	/// Aggregate session token economics and financial savings metrics.
48	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
49	pub struct TokenEconomics {
50	    pub input_tokens: u64,
51	    pub output_tokens: u64,
52	    pub cache_creation_tokens: u64,
53	    pub cache_read_tokens: u64,
54	    pub ephemeral_5m_tokens: u64,
55	    pub ephemeral_1h_tokens: u64,
56	    pub cache_hit_ratio: f32,
57	    pub total_cost_usd: f64,
58	    pub provided_cost_usd: Option<f64>,
59	    pub baseline_cost_no_cache_usd: f64,
60	    pub net_savings_usd: f64,
61	    pub efficiency_multiplier: f32,
62	    pub per_model: HashMap<CompactString, ModelTokenSummary>,
63	    pub reasoning_output_tokens: u64,
64	    /// `false` when `model_name` matched no seeded [`PricingTable`] row (see
65	    /// [`PricingTable::is_recognized`]) -- callers must render cost as an explicit "unknown",
66	    /// not `$0.00`, in that case. `total_cost_usd`/`net_savings_usd` are still `0.0` for an
67	    /// unpriced model (every rate lookup returns 0.0), so this flag is the only signal
68	    /// distinguishing a genuinely free session from an unpriced one.
69	    pub is_fully_priced: bool,
70	}
71	
72	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
73	pub struct ModelTokenSummary {
74	    pub input_tokens: u64,
75	    pub output_tokens: u64,
76	    pub cache_creation_tokens: u64,
77	    pub cache_read_tokens: u64,
78	    pub reasoning_tokens: u64,
79	    pub cost_usd: f64,
80	    pub turns: u64,
81	    /// See [`TokenEconomics::is_fully_priced`].
82	    pub is_fully_priced: bool,
83	}
84	
85	impl ModelTokenSummary {
86	    /// See [`TokenEconomics::cost`].
87	    pub fn cost(&self) -> Cost {
88	        if self.is_fully_priced {
89	            Cost::Priced(self.cost_usd)
90	        } else {
91	            Cost::Unpriced
92	        }
93	    }
94	}
95	
96	impl TokenEconomics {
97	    /// Computes full economic summary from one [`TurnPricingInput`] per turn. Each turn is
98	    /// priced independently via `pricing.rate_for` at that turn's own timestamp/tier, and the
99	    /// per-turn costs are summed into `total_cost_usd` -- required so a session whose turns
100	    /// straddle a price-change boundary is priced correctly on both sides. Token counters
101	    /// remain simple sums across turns, unaffected by the per-turn pricing. An empty `turns`
102	    /// slice returns a zeroed `TokenEconomics`, not an error.
103	    pub fn calculate(
104	        turns: &[TurnPricingInput],
105	        model_name: &str,
106	        pricing: &PricingTable,
107	        provided_cost_usd: Option<f64>,
108	    ) -> Self {
109	        let is_fully_priced = pricing.is_recognized(model_name);
110	
111	        let mut input_tokens = 0u64;
112	        let mut output_tokens = 0u64;
113	        let mut cache_creation_tokens = 0u64;
114	        let mut cache_creation_1h_tokens = 0u64;
115	        let mut cache_read_tokens = 0u64;
116	        let mut reasoning_tokens_total = 0u64;
117	        let mut total_cost_usd = 0.0f64;
118	        let mut baseline_cost_no_cache_usd = 0.0f64;
119	
120	        for turn in turns {
121	            let usage = &turn.usage;
122	            let tier = turn.tier.as_deref();
123	
124	            let input_rate = pricing.rate_for(model_name, tier, TokenRateKind::Input, turn.timestamp);
125	            let cache_write_5m_rate = pricing.rate_for(model_name, tier, TokenRateKind::CacheWrite, turn.timestamp);
126	            let cache_write_1h_rate = pricing.rate_for(model_name, tier, TokenRateKind::CacheWrite1h, turn.timestamp);
